"use client";

import { useEffect, useRef, useState } from "react";
import { ComposerPanel, type ComposerPanelProps } from "./composer";
import { type ComposerAttachment } from "./composer-attachment-strip";
export { ComposerAttachmentTile, ComposerAttachmentStrip } from "./composer-attachment-strip";
export type { ComposerAttachment, ComposerAttachmentKind, ComposerAttachmentTileProps, ComposerAttachmentStripProps } from "./composer-attachment-strip";

export interface ComposerWithAttachmentsProps extends Omit<ComposerPanelProps, "attachments" | "onRemoveAttachment"> {
  attachments: readonly ComposerAttachment[];
  onAttachmentsChange?: (attachments: ComposerAttachment[]) => void;
  /** Simulated transfer time, with small staggered percentage steps. */
  uploadDuration?: number;
  uploadGap?: number;
  onUploadComplete?: (attachment: ComposerAttachment) => void;
  onAllUploaded?: () => void;
}
/** Queued demonstrations share the same tiles as application-driven uploads. */
export function ComposerWithAttachments({ attachments, onAttachmentsChange, uploadDuration = 1100, uploadGap = 150, onUploadComplete, onAllUploaded, ...panel }: ComposerWithAttachmentsProps) {
  const latest = useRef({ attachments, onUploadComplete, onAllUploaded });
  latest.current = { attachments, onUploadComplete, onAllUploaded };
  const engine = useRef({ active: "", started: 0, updated: 0, value: 0, available: 0, completed: new Set<string>(), cycle: false });
  const [progress, setProgress] = useState<Record<string, number>>({});
  useEffect(() => {
    const state = engine.current, present = new Set(attachments.map(file => file.id));
    for (const id of state.completed) if (!present.has(id)) state.completed.delete(id);
    if (state.active && !present.has(state.active)) { state.active = ""; state.available = 0; }
    let frame: number;
    const tick = (now: number) => {
      const files = latest.current.attachments;
      if (!state.active && now >= state.available) {
        const next = files.find(file => file.progress === 0 && !state.completed.has(file.id));
        if (next) { state.active = next.id; state.started = now; state.updated = now + 200; state.value = 0; state.cycle = true; setProgress(previous => ({ ...previous, [next.id]: 0 })); }
        else if (state.cycle) { state.cycle = false; latest.current.onAllUploaded?.(); }
      }
      if (state.active) {
        const id = state.active;
        // A transfer-like cadence: independent small steps, rather than a frame-smooth counter.
        if (now - state.updated >= 50) {
          state.updated += 50;
          state.value = Math.min(100, state.value + (0.5 + Math.random()) * 5000 / Math.max(1, uploadDuration));
          const value = Math.round(state.value);
          setProgress(previous => previous[id] === value ? previous : { ...previous, [id]: value });
        }
        if (state.value === 100) {
          state.completed.add(id); state.active = ""; state.available = now + Math.max(0, uploadGap);
          const file = files.find(file => file.id === id);
          if (file) latest.current.onUploadComplete?.({ ...file, progress: 100 });
        }
      }
      if (state.active || files.some(file => file.progress === 0 && !state.completed.has(file.id)) || state.cycle) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [attachments, uploadDuration, uploadGap]);
  const visible = attachments.filter(file => file.progress !== 0 || engine.current.active === file.id || engine.current.completed.has(file.id));
  return <ComposerPanel {...panel} attachments={visible.map(file => file.progress === 0 ? { ...file, progress: engine.current.completed.has(file.id) ? 100 : progress[file.id] ?? 0 } : file)} onRemoveAttachment={id => onAttachmentsChange?.(attachments.filter(file => file.id !== id))} />;
}
